import{_ as r,a as t,b as l,c as i,d as o,e as n}from"./chunks/4d1839597d3ee12b8528.CstY2vHb.js";import{_ as s,C as h,o as u,c as d,j as p,a as A,E as g,a6 as I}from"./chunks/framework.CnPv4DE1.js";const C=JSON.parse('{"title":"学习AI，让任何其他技能放大10倍（完整新手指南）","description":"","frontmatter":{"title":"学习AI，让任何其他技能放大10倍（完整新手指南）","originalTitle":"Learn AI To 10x Any Other Skill (Full Beginner Guide)","date":"2025-03-15","originalUrl":"https://thedankoe.com/letters/learn-ai-to-10x-any-other-skill-full-beginner-guide/","minutes":14,"sourceHash":"e8ba409fd3633f54494b40aa1b368379692fbf2696729f739ac01b4b184ae2b3","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/learn-ai-to-10x-any-other-skill-full-beginner-guide/"}]]},"headers":[],"relativePath":"letters/learn-ai-to-10x-any-other-skill-full-beginner-guide.md","filePath":"letters/learn-ai-to-10x-any-other-skill-full-beginner-guide.md"}'),c={name:"letters/learn-ai-to-10x-any-other-skill-full-beginner-guide.md"};function m(b,e,f,k,x,_){const a=h("ArticleMeta");return u(),d("div",null,[e[0]||(e[0]=p("h1",{id:"学习ai-让任何其他技能放大10倍-完整新手指南",tabindex:"-1"},[A("学习AI，让任何其他技能放大10倍（完整新手指南） "),p("a",{class:"header-anchor",href:"#学习ai-让任何其他技能放大10倍-完整新手指南","aria-label":'Permalink to "学习AI，让任何其他技能放大10倍（完整新手指南）"'},"​")],-1)),g(a),e[1]||(e[1]=I('<p><a href="https://www.youtube.com/embed/3Nrrqzuox2Q?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>AI是你目前能掌握的最新、最棒的高价值技能。</p><p>但它跟其他技能不一样。</p><p>现阶段别人叫你去学的那些“高收入”技能——比如邮件营销、社交媒体、网页设计、编程等等——注定会随着技术的发展而改变，而且这一切正在发生。</p><p>AI是一项新的元技能，当你把它与你拥有的任何数字技能结合时，它的价值会放大10倍。</p><p>现在，你们中有些人可能会感到怀疑。</p><p><strong>“Dan，你不是写过大概5篇通讯，说AI不会取代创意工作吗？”</strong></p><p>没错，很多人误解了这一点，认为我反AI，因为他们看待问题非黑即白。</p><p><strong>“AI会毁灭世界，毁掉所有的创造力，并剥夺我们的目标感源泉。”</strong></p><p>不，它只会毁掉那些早已沦为机器的人的生活，这些人被一个专门培育好用打工人的系统所驯化。那些<em>不</em>去追求自己的道路、创造自己的工作、寻找自己目标的人。</p><p><strong>“人们越使用AI，就会变得越蠢。”</strong></p><p>是的，有些人如果把思考外包给AI，确实会变蠢。但现实情况是，AI可以大幅敏锐你的思维，帮你学得更快，并从你的生活中消除大量的琐事——让你能专注于你享受的事物。你的手艺。</p><p>问题在于，95%的人连AI最纯粹的基础都不懂。</p><p>他们在里面敲下一句话，就指望它能改变自己的人生。</p><p>AI是一项技能。</p><p>而关于技能，最重要的一点就是你需要去学习它、练习它，并把它应用到你的生活中。</p><p>所以，我想给你们上一堂关于现阶段AI的迷你大师课。</p><p>这样一来，你就能比大多数迟钝的人更快地改变你的生活和工作。</p><p>我们将要：</p><ul><li>拆解AI运作的绝对基础原理</li><li>讲解AI的不同模型、工具和用例（因为大多数人以为世界上只有ChatGPT）</li><li>学习如何通过从“任务思维”转变为“系统思维”来编写有效的提示词</li><li>我会给你一个专门用来写出更有效提示词的提示词，这样你就能超越99%使用AI的人</li><li>学习AI的实际用例，每周节省数小时的工作时间，提高你的生活质量，并增加你在创意上获得成功的几率</li></ul><p>我还会向你展示我是如何写提示词，在10秒内写出15篇疯传社交帖子的。</p><p>以及如何完美模仿任何人的语调，或者生成有利可图的商业点子。</p><p>我们有很多要聊的。</p><p>这部分的第一节对你来说可能有点无聊。</p><p>但如果你是来学习的，你就会明白学习并不总是好玩的。它需要努力，需要你坚持下去，即使它不像你习惯的那样能提供一连串廉价的多巴胺刺激。学习的大部分时间里，你都会觉得好像什么都没学到。</p><p>拿出你的笔记本，我们开始吧。</p><h2 id="ai模型与工具基础" tabindex="-1">AI模型与工具基础 <a class="header-anchor" href="#ai模型与工具基础" aria-label="Permalink to &quot;AI模型与工具基础&quot;">​</a></h2><p>我会尽量让这部分保持简短。</p><p>实际上，我让AI把这部分内容浓缩了一半，因为我实在不喜欢写技术类的内容。</p><p>如果你只关心如何写提示词并把AI应用到你的工作流中，你可以直接跳过这部分。</p><p>如果你不是在开发AI，或者不是在AI公司工作，你可能不需要了解它所有的内部运作机制，就像你不需要知道怎么开发邮件营销软件就能使用它一样，但有一个宏观的了解是有帮助的。</p><blockquote><p>如果你想全面深入地了解LLM，去看看<a href="https://youtu.be/7xTGNNLPyMI" target="_blank" rel="noreferrer">Andrej Karpathy的视频</a>。作为OpenAI的创始成员，他绝对是懂行的。</p></blockquote><h3 id="基础模型" tabindex="-1">基础模型 <a class="header-anchor" href="#基础模型" aria-label="Permalink to &quot;基础模型&quot;">​</a></h3><p>LLM（Large Language Models，大语言模型）就是我们今天所说的“AI”。</p><p>当你和它聊天时，你的文本会被转换成“tokens（词元）”进行处理。把token想象成单词的碎片——有时是一个完整的词，有时是词的一部分。例如，“chatting”可能会被拆分成“chat”和“ting”两个单独的token。这就是AI消化文本的方式，大多数模型一次能处理数千个token。</p><p>每次新的聊天都会开启一个全新的“上下文窗口（context window）”，它决定了AI能访问或记住哪些token。你和AI聊得越多，token流就越大，如果你超出了上下文窗口（ChatGPT 4o拥有128k token的上下文窗口），它可能就会开始忘记里面的内容，因为旧内容被挤出去了。</p><p>主要的玩家和模型包括：</p><ul><li>OpenAI (ChatGPT)</li><li>Anthropic (Claude)</li><li>Google (Gemini)</li><li>xAI (Grok)</li><li>Meta (Llama)</li><li>LeChat (Mistral)</li><li>Deepseek (V3)</li></ul><p>每家公司都会随着时间推移发布改进后的模型（比如Claude Sonnet 3.7或ChatGPT 4.5）。模型的不同之处在于：</p><ul><li><strong>预训练（Pre-training）</strong>：模型从通常是6个月以前的数据中学习，这意味着除非连接到搜索，否则它们不知道最近发生的事件。就像它们把互联网读到了某个特定日期，然后就停了。</li><li><strong>后训练（Post-training）</strong>：决定了个性和语调（对比一下ChatGPT 4o和4.5，或者试试Grok的“无过滤模式”）。</li><li><strong>上下文窗口（Context Window）</strong>：AI在一次对话中能“记住”的文本量。像Gemini这样的模型可以一次性处理整本书，而其他模型可能会忘记冗长对话的前半部分。</li><li><strong>定价（Pricing）</strong>：范围很广（Deepseek V3和Gemini比Claude便宜）。</li></ul><p>不同的模型擅长不同的任务。Claude Sonnet在写作和编程方面占据统治地位，但如果你用它来进行海量信息处理，跟Gemini比起来可能会非常昂贵。</p><p>我建议你试试免费额度，或者使用一款允许你在多个模型之间切换的软件，以便针对所需任务使用任意模型。<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 本周就会推出这个功能。</p><h3 id="思考模型" tabindex="-1">思考模型 <a class="header-anchor" href="#思考模型" aria-label="Permalink to &quot;思考模型&quot;">​</a></h3><p>当基础模型不够用时，像ChatGPT o1、Claude Sonnet 3.7（在思考模式下）或Deepseek R1这样的“推理”或“思考”模型能提供额外的处理能力。</p><p>这些模型更贵，但通过可见的“思考”过程，模拟了人类般的解决问题能力：</p><p><img src="'+r+'" alt=""></p><p>当你需要对复杂写作进行深度分析，或需要超越基础知识的专业编程时，它们绝对物有所值。</p><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><p>尽管功能强大，但LLM仍有局限性：</p><ul><li>无法访问当前实时信息</li><li>一次只能处理一个提示词</li><li>除非得到特别指示，否则都是通用的</li></ul><p>互联网搜索和深度搜索（DeepResearch）工具填补了这些空白。Perplexity作为“打激素的谷歌搜索”脱颖而出——它能提供高度相关的信息，UI也极佳。我现在用它的频率远远超过谷歌搜索。</p><p>Perplexity、ChatGPT等平台提供的DeepResearch功能，将互联网搜索与扩展的思考能力结合在了一起。在得到正确指示的情况下，它会吐出全面的研究内容和信息来源供你探索和核实，为创作者和研究人员节省了数小时的时间。</p><h3 id="套壳产品-wrappers" tabindex="-1">套壳产品 (Wrappers) <a class="header-anchor" href="#套壳产品-wrappers" aria-label="Permalink to &quot;套壳产品 (Wrappers)&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>套壳产品（Wrappers）将LLM与用于特定工作流的专业工具整合在一起。</p><p>这就是现在大多数初创公司正在构建的东西，因为它们可以采用基础模型，并使其在特定的应用场景中更加有效。</p><ul><li><strong>Perplexity</strong>：将多个LLM与互联网搜索结合（截至1月份，ARR达8000万美元）</li><li><strong>Cursor</strong>：集成了AI的编程IDE，可以访问你的代码库（在不到2年的时间里，ARR从100万美元增长到了1亿美元——比OpenAI还快）</li><li><strong>Kortex</strong>：一个汇集你的工作、笔记、划线高亮和想法的中心枢纽，你可以用AI快速参考这些内容。</li></ul><p>虽然你可以在工作时同时开着ChatGPT，但这些专业的套壳产品内置了更多的提示词工程，并拥有不同的UI界面，从而让它们在特定情况下更加实用。</p><p>你可以把OpenAI想象成新的沃尔玛，而套壳产品就是新的保健品专卖店。</p><h2 id="学习这项新技能——提示词工程" tabindex="-1">学习这项新技能——提示词工程 <a class="header-anchor" href="#学习这项新技能——提示词工程" aria-label="Permalink to &quot;学习这项新技能——提示词工程&quot;">​</a></h2><p>在AI领域变“强”，关键在于从“任务思维者”转变为“系统思维者”。</p><p>当你为了实现诸如写15篇社交媒体帖子之类的目标，去编写提示词或一连串提示词时，你其实是在用书面文本构建一个系统。</p><p>就像写代码一样：</p><ul><li>你对项目有一个愿景</li><li>你了解实现这一目标的步骤</li><li>你尽你所知去执行任务，直到它完成</li></ul><p>AI不会改变实现某件事的过程，它只是帮你做得更快，让你能够获取更多知识，并从整体上帮助你克服或避开盲区。它有助于快速做出更高质量的决策。</p><p>所以，如果你学会了如何使用AI，你就能构建得更快，学得更快，并降低失败的几率。</p><p>但这同时也带来了一个陷阱：</p><p>AI无法弥补个人能力的缺失。</p><p>AI不是你潜意识里一直在寻找的那张暴富门票，而这可能正是你阅读本文的原因。</p><p>在AI里敲下一句话，指望它一发入魂完成你想要的任何任务，这是很愚蠢的，而且会让你一事无成。</p><p>当然，如果你只是搜索信息以获取一个快速答案，那往Perplexity里扔一句话是完全没问题的。</p><p>但对于大多数其他用例，你需要长得多且更详细的东西。</p><h3 id="如何写出杀手级提示词" tabindex="-1">如何写出杀手级提示词 <a class="header-anchor" href="#如何写出杀手级提示词" aria-label="Permalink to &quot;如何写出杀手级提示词&quot;">​</a></h3><p>提示词有两种类型：</p><ul><li><strong>系统或元提示词（meta prompt）</strong> —— 你发送的第一个提示词，用于为你试图实现的整个对话或任务设定框架。</li><li><strong>后续提示词</strong> —— 较短的提示词，用于完善输出结果或进一步深挖。</li></ul><p>我们将把重点放在元提示词上，因为这对你来说会产生最大的改变。</p><p>一个好的元提示词有很多种写法，但我喜欢把它们分成5个部分来写：</p><ul><li><strong>系统（System）</strong> —— 分配一个角色，并对任务进行描述。</li><li><strong>背景（Context）</strong> —— 提供参考信息或你对想做之事的预期。</li><li><strong>指示（Instructions）</strong> —— 完成该任务的详细指令。</li><li><strong>示例（Examples，可选）</strong> —— 如果你有具体的例子，比如社交帖子模板，你可以像我们在下面那样把它们加进去。</li><li><strong>约束（Constraints）</strong> —— 要避免或包含哪些可能未被考虑在内的内容。</li><li><strong>输出（Output）</strong> —— 你希望输出如何排版，这与示例不同。</li></ul><p>这是一个我制作的内容总结提示词示例，用来总结书籍和YouTube视频，因为大多数通用的AI总结都很烂，根本给不了你任何有用信息。</p><p>相比之下，这个提示词正好能给我想要的东西，让我在想要引用信息源时，能够进行深刻细腻的写作。</p><p><img src="'+l+'" alt=""></p><p>这种做法的美妙之处在于，你可以写一次提示词，把它存进像Kortex这样的软件的笔记或文档里，随时需要随时调用。</p><p>更美妙的是，<a href="https://stan.store/thedankoe/p/prompt-library" target="_blank" rel="noreferrer">我这里有一个提示词，你可以用它来_为你写出更好的提示词。_</a></p><p>我们讨论的大多数提示词都在里面。</p><p>是的，需要你留下邮箱才能获取，因为我想把它们放进一个带有说明指导的课程风格平台里。</p><p>所以，只要你想创建一个提示词，就先把这个“元提示词创建器”粘贴到AI工具里，最好是像Claude 3.7或ChatGPT o1这样的推理模型。</p><p>现在，你必须对其进行几次微调才能做到恰到好处，所以我们来过一遍这个流程。</p><p>如果我想让AI帮我写一批能疯传的社交媒体帖子，我会这么做：</p><p><strong>1) 给出尽可能多的细节。</strong></p><p>把 AI 想象成一个聪明的人,但他<strong>没有任何具体信息</strong>。</p><p>如果你直接让他们做点什么,他们能做出还算不错的东西,但要让它变得惊艳,你需要给他们具体的指令和细节。</p><p><strong>1.5) 或者给自己写一份简短的指南,说明你是如何写帖子的。</strong></p><p>这可能需要一些时间,但请记住,如果你把提示词写对了,你就可以反复使用它——从而在工作时间上省下大把大把的时间。</p><p>我把「元提示词创建器(Meta Prompt Creator)」粘贴进了 Claude Sonnet(不久之后也会内置到 Kortex 里)。</p><p>然后,我拿了一条<a href="https://app.kortex.co/public/document/4db696c4-bbf3-4032-b0f1-8caa68c83f6b" target="_blank" rel="noreferrer">我之前自己写的提示词</a>——我知道它还可以更好——把它输入进去。</p><p><strong>2) 测试一下并加以完善。</strong></p><p>最初的输出结果还算可以。但我知道加上例子会更好。</p><p>于是,我翻了翻自己的素材库(swipe file),又在 X 上搜索了自己表现最好的帖子,以及我喜欢的别人写的帖子。</p><p>我在提示词「指令(Instructions)」部分下面加了一个「示例(Examples)」子部分,然后再试了一次。</p><p>效果好多了。</p><p><img src="'+i+'" alt=""></p><p><strong>3) 把输出结果打磨到位。</strong></p><p>有时候 AI 在格式上会搞得一团糟。</p><p>对于社交媒体帖子,它把所有内容都堆在一起,没有换行也没有分隔。它是能用,但我想让它们看起来都像真正的帖子。</p><p>这里有个例子,我让 kAI 用社交帖子提示词,从我两周前的通讯邮件里提炼想法。</p><p>虽然这些帖子还不错,听起来也像我的风格,但我把这看作一种提炼想法的方式——这些想法本来就是我<em>已经从通讯邮件里提炼出来的</em>。当你手边已经有潜在的推文时,用「推文的方式」去思考会更容易。</p><p><img src="'+o+'" alt=""></p><p><img src="'+n+'" alt=""></p><p>用这个提示词几次之后,继续做一些细微的调整,直到它稳定下来。</p><h2 id="如何每周省下数小时——ai-的使用场景" tabindex="-1">如何每周省下数小时——AI 的使用场景 <a class="header-anchor" href="#如何每周省下数小时——ai-的使用场景" aria-label="Permalink to &quot;如何每周省下数小时——AI 的使用场景&quot;">​</a></h2><p>我无法放弃我的写作。</p><p>我太喜欢写作了(尽管我让 AI 压缩了这篇邮件的第一部分……我不喜欢写技术性的东西)。</p><p>这让我开始思考 AI 应该被用来做什么:</p><p><em>AI 应该被用来强化你热爱的创造性工作,并自动化你厌恶的琐碎工作。</em></p><p>对某些人来说,他们的琐碎工作可能就是写作。他们可能很讨厌写作。如果他们想让 AI 批量吐出一堆 SEO 文章,或者帮他们写一堆社交帖子,我倒不觉得这是个问题。</p><p>AI 应该被用来帮助你专注于你的手艺,并在其中表现得更好。</p><p>所以,为了搞清楚 AI 能怎样最好地帮到你,把下面这些写出来:</p><ul><li>你每天都做些什么?</li><li>哪些部分你很喜欢,不想放弃?</li><li>哪些部分你很讨厌,并且不需要创造力?</li><li>你要如何把 AI 融入你的日常流程,并建立一个提示词库,帮你更快地完成那些你讨厌的工作?</li></ul><p>即使 AI 没有帮你在创造性工作上省时间,这重要吗?因为更好的信息能提升那份工作的质量。</p><p>下面是几个可能的使用场景,但还有更多场景,你可以自己创建相应的提示词。</p><p>当你创建提示词时,把它们存到你的笔记应用里,这样你就能快速调用。</p><h3 id="使用场景-1——新时代的谷歌搜索" tabindex="-1">使用场景 1——新时代的谷歌搜索 <a class="header-anchor" href="#使用场景-1——新时代的谷歌搜索" aria-label="Permalink to &quot;使用场景 1——新时代的谷歌搜索&quot;">​</a></h3><p>如果现在的 AI 模型没有让你的生产力至少提升 2 倍,那说明你用错了方法,或者你还没有改变自己现有的习惯,去偏向使用 AI。</p><p>对于和我年纪相仿的人来说,你大概能理解那种挣扎:你妈问你一个问题,而你立刻在心里想,「她干嘛不直接谷歌搜一下?」</p><p>作为孩子,我这一代人以及我之前的那些人,天生就拥有一种生产力超能力,因为我们能用谷歌。我们可以发现新的机会,探索自己的好奇心,并在不用翻教科书、不用写信给某个专家的情况下,得到问题的答案。</p><p>这是每个个体都拥有的一种惊人的力量。</p><p>对你来说,这可能看起来是个「无聊」的 AI 使用场景,但我可以向你保证,它是所有场景中最强大的一个。</p><p>想象一下谷歌搜索为你的人生做了什么,然后把那种效果乘以 10 倍。</p><p>你该这样做:</p><ul><li>重新训练你的习惯,每当你想问谷歌一个问题时,就打开一个 AI 工具。</li><li>使用像 Perplexity 这样的搜索工具快速提问——你还可以持续追加提问,深入挖掘。</li><li>在电脑上工作时,使用像 <a href="https://kortex.co/download" target="_blank" rel="noreferrer">Kortex</a> 这样的工具,你可以按 Alt 或 Option+C,在工作时打开一个悬浮的 AI 聊天窗口。</li></ul><p>当你在 Photoshop、Canva、Figma 中卡壳,或是在剪辑视频、写帖子、编程,或做任何其他事情时,选择合适的模型,把问题问出来,更快地克服困难。</p><h3 id="使用场景-2——更快地学习-智力陪练伙伴" tabindex="-1">使用场景 2——更快地学习 &amp; 智力陪练伙伴 <a class="header-anchor" href="#使用场景-2——更快地学习-智力陪练伙伴" aria-label="Permalink to &quot;使用场景 2——更快地学习 &amp; 智力陪练伙伴&quot;">​</a></h3><p>如果成功的关键在于拥有正确的知识并加以实践,那么 AI 至少能在第一部分上帮到你。</p><p>不管你是在:</p><ul><li>学习一门新语言</li><li>试图理解一本晦涩的书</li><li>试图在一份 PDF 里找到某条具体信息并加以总结</li></ul><p>AI 都可以被当作一个智力陪练伙伴。</p><p>你可以把一本书的章节粘贴进 AI 模型,在阅读的同时让它深入挖掘某些具体的概念。</p><p>你可以写一个提示词,把 AI 变成一个语言教练,教你学习并测试你的进度。</p><p>你可以把整份 PDF 喂给像 Gemini 这样的模型,不用翻页或做书签,就能找到你需要的信息。</p><p>我打算专门写一篇完全独立的邮件,讲讲如何借助 AI 读书,因为我听到过一些相当愚蠢的言论,说「AI 会让读书变得无关紧要」。</p><h3 id="使用场景-3——为创造性工作或创业提供想法生成" tabindex="-1">使用场景 3——为创造性工作或创业提供想法生成 <a class="header-anchor" href="#使用场景-3——为创造性工作或创业提供想法生成" aria-label="Permalink to &quot;使用场景 3——为创造性工作或创业提供想法生成&quot;">​</a></h3><p>如果你正在写一本书、一份通讯、一个 YouTube 脚本,或者任何需要创意想法的东西,你可以做以下几件事:</p><ul><li>给 AI 提供一个灵感来源,比如一个书的章节或一条社交帖子,让它拆解这段内容的结构,以及它为什么有效。</li><li>给 AI 你的目标受众,让它给出 10 个相关的痛点、10 个欲望,并基于每一项给出 20 个标题或帖子创意。</li><li>像我们上面做的那样,创建一个用于写帖子、大纲或完整文章的提示词,并用它们来提炼潜在的想法。我的通讯邮件和 YT 脚本提示词就放在我的<a href="https://thedankoe.com/links" target="_blank" rel="noreferrer">提示词与模板库</a>里。</li><li>在你写作的过程中,让 AI 用另一个人的声音——比如一位斯多葛派哲学家——重写某些具体的句子或段落,从而获得对这个想法的不同视角。</li></ul><p>当你想开始做一件新事情,比如一个生意或创业项目时,有很多东西需要考虑。这个想法可行吗?值得去做吗?市场上有竞争对手吗?</p><p>你可以使用或创建像<a href="https://prompt-files.com/prompts/index.html" target="_blank" rel="noreferrer">「商业想法分析」提示词</a>这样的工具,一次性获得所有信息。AI 的调研速度比你快得多。</p><h3 id="使用场景-4——客户形象与语言风格分析" tabindex="-1">使用场景 4——客户形象与语言风格分析 <a class="header-anchor" href="#使用场景-4——客户形象与语言风格分析" aria-label="Permalink to &quot;使用场景 4——客户形象与语言风格分析&quot;">​</a></h3><p>如果你是一名不太想花心思在营销、写落地页、促销文案等事情上的写作者,你在这方面可以玩出不少花样。</p><ul><li>提取一段 YouTube 视频的内容,写一个提示词,拆解其结构、风格和语调,据此撰写 YouTube 脚本。</li><li>创建一个客户形象(customer avatar),这样你每次用 AI 制作营销素材时都可以拿来参考。比如,把上面那个 YouTube 脚本拿来,让它专门针对你的客户形象生成内容。</li></ul><p>最后,也是我最喜欢的一点,是基于一篇参考文本创建一份<a href="https://app.kortex.co/public/document/115739af-596f-46fb-95b7-56a18fb76e7a" target="_blank" rel="noreferrer">完整的语言风格分析</a>。</p><p>你可以把任意一本书的章节、一份通讯邮件或一段转录文字,喂给这个详尽的语言风格分析提示词,然后把结果存进你的笔记里备用。</p><p>然后,你可以把这个结果和大纲框架、几个想法搭配起来,让 AI 完全按照那个人的方式去写作。</p><p>相当离谱。真的,试试这个。</p><h3 id="使用场景-5——个人成长与清晰思考" tabindex="-1">使用场景 5——个人成长与清晰思考 <a class="header-anchor" href="#使用场景-5——个人成长与清晰思考" aria-label="Permalink to &quot;使用场景 5——个人成长与清晰思考&quot;">​</a></h3><p>我想你们大多数人都在之前的邮件和视频里,见过「战略顾问(Strategic Advisor)」提示词有多厉害。</p><p>但你可以用它做的远不止这些。</p><ul><li>你可以让它把你的目标拆解成可执行的任务和习惯。</li><li>你可以直接把日记写进 AI,让它告诉你关于你自己的事,好的和不好的都说。</li><li>你可以让它<a href="https://prompt-files.com/prompts/index.html" target="_blank" rel="noreferrer">找出你问题的根本原因</a>,并给你解决问题的洞见。</li><li>你可以让 AI 变成一个纯逻辑的问题解决者,把情绪从整个决策过程中剔除出去。</li></ul><p>我就先说到这里,因为我现在只是在不断地向你灌输各种可能的使用场景,这可能会让人有点吃不消了。</p><p>我想让你做的是这件事:</p><p>想一想那些你必须做、但又不想做的事情,比如:</p><ul><li>为 SEO 写博客文章</li><li>保持在社交媒体上的活跃度(创造性写作并不适合每个人)</li><li>预订机票、雇佣个人助理,或是整理各种任务</li></ul><p>然后开始从大局出发,思考你可以创建哪一系列的提示词,帮你更快地完成这些事情,或者把它们彻底自动化。</p><p>希望这篇邮件对你有帮助,也希望你能找到一些有意思的东西去尝试一下 🙂</p><hr><p><a href="/en/letters/learn-ai-to-10x-any-other-skill-full-beginner-guide">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',164))])}const T=s(c,[["render",m]]);export{C as __pageData,T as default};
